-- Hapus SEMUA objek dengan prefix APX_MBMS_ (termasuk custom SQL). HANYA untuk sandbox.
begin
   for r in (select object_type
                   ,object_name
               from user_objects
              where object_name like 'APX\_MBMS\_%' escape '\'
                and object_type in ('VIEW', 'TRIGGER', 'PACKAGE', 'PROCEDURE', 'FUNCTION', 'TABLE', 'SEQUENCE', 'TYPE')
              order by decode(object_type, 'VIEW', 1, 'TRIGGER', 2, 'PACKAGE', 3, 'PROCEDURE', 4, 'FUNCTION', 5, 'TABLE', 6, 7))
   loop
      begin
         execute immediate 'drop ' || r.object_type || ' ' || dbms_assert.simple_sql_name(r.object_name)
                           || case r.object_type when 'TABLE' then ' cascade constraints purge' end;
      exception
         when others then
            if sqlcode not in (-4043, -942) then -- sudah terhapus (mis. tabel ikut terhapus)
               raise;
            end if;
      end;
   end loop;
end;
/
